/* From Uiverse.io by barisdogansutcu - Tags: switch */
.__UIV_SCOPE__ label {
 background-color: white;
 display: flex;
 align-items: center;
 gap: 14px;
 padding: 10px 15px 10px 10px;
 cursor: pointer;
 user-select: none;
 border-radius: 10px;
 box-shadow: rgba(149, 157, 165, 0.2) 0px 8px 24px;
 color: black;
}

.__UIV_SCOPE__ input {
 display: none;
}

.__UIV_SCOPE__ input:checked + label svg {
 fill: hsl(0deg 100% 50%);
 stroke: hsl(0deg 100% 50%);
 animation: heartButton 1s;
}

@keyframes heartButton {
 0% {
  transform: scale(1);
 }

 25% {
  transform: scale(1.3);
 }

 50% {
  transform: scale(1);
 }

 75% {
  transform: scale(1.3);
 }

 100% {
  transform: scale(1);
 }
}

.__UIV_SCOPE__ input + label .action {
 position: relative;
 overflow: hidden;
 display: grid;
}

.__UIV_SCOPE__ input + label .action span {
 grid-column-start: 1;
 grid-column-end: 1;
 grid-row-start: 1;
 grid-row-end: 1;
 transition: all .5s;
}

.__UIV_SCOPE__ input + label .action span.option-1 {
 transform: translate(0px,0%);
 opacity: 1;
}

.__UIV_SCOPE__ input:checked + label .action span.option-1 {
 transform: translate(0px,-100%);
 opacity: 0;
}

.__UIV_SCOPE__ input + label .action span.option-2 {
 transform: translate(0px,100%);
 opacity: 0;
}

.__UIV_SCOPE__ input:checked + label .action span.option-2 {
 transform: translate(0px,0%);
 opacity: 1;
}
